"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["58471"],{37990(e){e.exports=JSON.parse('{"id":"FIN-997","slug":"index-number","term":"Index Number","also_known_as":[],"difficulty":"Intermediate","definition":"An index number is a figure that shows how a value has changed relative to a base period, which is usually set equal to 100.","explanation":["Index numbers make it easy to compare changes over time, especially for quantities measured in different units or combining many items.","For example, if the average price of a basket of goods was 50 in the base year and is 55 today, the price index is 110, showing a 10% increase since the base year.","Many important economic statistics are expressed as index numbers. The Consumer Price Index measures changes in the cost of living. Stock market indices, such as major benchmark indices around the world, track the combined value of groups of shares. Index numbers are also used for house prices, wages, production and many other measures.","Index numbers can be simple, tracking a single item, or composite, combining many items. Composite indices assign weights to their components, reflecting their importance. For example, a consumer price index gives more weight to housing and food than to items that make up a small share of household spending.","Index numbers show relative change, not absolute values. An index of 120 means a 20% rise from the base, but says nothing about the actual price level. Comparing two index values directly shows the percentage change between them."],"note":"","total":1500,"prev":{"slug":"index-fund","term":"Index Fund"},"next":{"slug":"indirect-cost","term":"Indirect Cost"}}')}}]);